// Package textutil provides helpers for character-set conversion and
// Unicode normalization.
package textutil

import (
	"fmt"
	"io"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/htmlindex"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// Lookup returns the encoding for a WHATWG/IANA name such as
// "utf-8", "shift_jis", "windows-1252" or "iso-8859-1".
func Lookup(name string) (encoding.Encoding, error) {
	enc, err := htmlindex.Get(name)
	if err != nil {
		return nil, fmt.Errorf("unknown encoding %q: %w", name, err)
	}
	return enc, nil
}

// DecodeToUTF8 converts b from the named encoding to UTF-8.
func DecodeToUTF8(b []byte, from string) (string, error) {
	enc, err := Lookup(from)
	if err != nil {
		return "", err
	}
	out, _, err := transform.Bytes(enc.NewDecoder(), b)
	return string(out), err
}

// EncodeFromUTF8 converts UTF-8 s to the named encoding. Characters that
// cannot be represented cause an error.
func EncodeFromUTF8(s, to string) ([]byte, error) {
	enc, err := Lookup(to)
	if err != nil {
		return nil, err
	}
	out, _, err := transform.Bytes(enc.NewEncoder(), []byte(s))
	return out, err
}

// NewDecodingReader wraps r so that reads yield UTF-8 decoded from the
// named encoding. Use this for large inputs instead of DecodeToUTF8.
func NewDecodingReader(r io.Reader, from string) (io.Reader, error) {
	enc, err := Lookup(from)
	if err != nil {
		return nil, err
	}
	return transform.NewReader(r, enc.NewDecoder()), nil
}

// Normalize returns s in the given Unicode normalization form
// (norm.NFC, norm.NFD, norm.NFKC or norm.NFKD).
func Normalize(s string, form norm.Form) string {
	return form.String(s)
}

// Equal reports whether a and b are canonically equivalent, i.e. equal
// after NFC normalization.
func Equal(a, b string) bool {
	return norm.NFC.String(a) == norm.NFC.String(b)
}
EOF
cat > textutil/textutil_test.go <<'EOF'
package textutil

import (
	"testing"

	"golang.org/x/text/unicode/norm"
)

func TestRoundTripLatin1(t *testing.T) {
	const s = "café"
	b, err := EncodeFromUTF8(s, "iso-8859-1")
	if err != nil {
		t.Fatal(err)
	}
	if len(b) != 4 {
		t.Fatalf("expected 4 bytes in Latin-1, got %d", len(b))
	}
	got, err := DecodeToUTF8(b, "iso-8859-1")
	if err != nil {
		t.Fatal(err)
	}
	if got != s {
		t.Fatalf("got %q, want %q", got, s)
	}
}

func TestDecodeShiftJIS(t *testing.T) {
	got, err := DecodeToUTF8([]byte{0x93, 0xfa, 0x96, 0x7b}, "shift_jis")
	if err != nil {
		t.Fatal(err)
	}
	if got != "日本" {
		t.Fatalf("got %q, want %q", got, "日本")
	}
}

func TestEncodeUnrepresentable(t *testing.T) {
	if _, err := EncodeFromUTF8("日本", "iso-8859-1"); err == nil {
		t.Fatal("expected error encoding CJK to Latin-1")
	}
}

func TestUnknownEncoding(t *testing.T) {
	if _, err := Lookup("not-a-charset"); err == nil {
		t.Fatal("expected error")
	}
}

func TestNormalize(t *testing.T) {
	composed := "é"    // é
	decomposed := "é" // e + combining acute
	if Normalize(decomposed, norm.NFC) != composed {
		t.Error("NFC did not compose")
	}
	if Normalize(composed, norm.NFD) != decomposed {
		t.Error("NFD did not decompose")
	}
	if Normalize("ﬁ", norm.NFKC) != "fi" { // ﬁ ligature
		t.Error("NFKC did not fold ligature")
	}
	if !Equal(composed, decomposed) {
		t.Error("expected canonical equivalence")
	}
}
